/**
 * Reports — PDF, JSON, CSV and Markdown generated by the engine's own report
 * functions (toPdf / toJson / toCsv / toMarkdown) inside the worker, then
 * saved through a Blob. The outline shows what each of the 11 sections will
 * contain for the loaded analysis.
 */
import { useState } from 'react'
import { FileDown, FileJson, FileSpreadsheet, FileText, FileType } from 'lucide-react'
import type { LucideIcon } from 'lucide-react'
import type { AnalysisResult } from '@interlock/core/types'
import { engine } from '../../engine/client.ts'
import type { ReportFormat } from '../../engine/protocol.ts'
import { AnalysisGate } from '../../features/AnalysisGate.tsx'
import { safeSlug } from '../../features/findings/meta.ts'
import { downloadBlob } from '../../lib/download.ts'
import { formatBytes, formatMs, formatTimestamp } from '../../lib/format.ts'
import { useDocumentTitle } from '../../lib/hooks.ts'
import { LocalModeIndicator } from '../../shell/LocalModeIndicator.tsx'
import { Button } from '../../ui/Button.tsx'
import { PageHeader } from '../../ui/Panel.tsx'
import { toast } from '../../ui/Toast.tsx'

const FORMATS: Array<{ id: ReportFormat; ext: string; label: string; icon: LucideIcon; body: string }> = [
  { id: 'pdf', ext: 'pdf', label: 'PDF report', icon: FileText, body: 'The full review document, all 11 sections, for sign-off and change records.' },
  { id: 'md', ext: 'md', label: 'Markdown', icon: FileType, body: 'The same document as text, for merge requests, wikis and diffs between runs.' },
  { id: 'csv', ext: 'csv', label: 'CSV', icon: FileSpreadsheet, body: 'One row per finding: severity, rule, safety functions, location, blast radius, before/after.' },
  { id: 'json', ext: 'json', label: 'JSON', icon: FileJson, body: 'The complete analysis result (interlock.analysis/v1), every change, finding and piece of evidence.' },
]

function outline(r: AnalysisResult): Array<[string, string]> {
  const review = r.findings.filter((f) => f.disposition === 'REVIEW' || f.disposition === 'UNDECLARED')
  const safety = r.findings.filter((f) => f.safetyFunctionIds.length > 0 && f.disposition === 'REVIEW')
  const notif = r.findings.filter((f) => f.notificationImpact !== 'NONE')
  const changedModules = r.modules.filter((m) => m.changed)
  const evidence = r.findings.reduce((n, f) => n + f.evidence.length, 0)
  const s = r.surface
  return [
    ['Executive summary', `Review priority ${s.priority}, trust ${r.trust.status.replace(/_/g, ' ')}, coverage ${r.coverage.percent}%, ${s.totalChanges} changes, ${s.safetyRelevant} safety-relevant.`],
    ['Project metadata', `${r.baseline.file.name} and ${r.current.file.name}: controller, processor, firmware, export dates and SHA-256 of both files.`],
    ['Analysis scope', `${r.manifest.functions.length} declared safety functions, declared non-safety scope, coverage of functions, routines, module relationships and notification paths.`],
    ['Change summary', `${s.totalChanges} changes by category, ${s.meaningfulLogicChanges} meaningful logic changes.`],
    ['Safety-relevant findings', `${safety.length} finding${safety.length === 1 ? '' : 's'} with before/after firing conditions, explanation and recommendation.`],
    ['Alarm and notification findings', notif.length ? `${notif.length} finding${notif.length === 1 ? ' that changes' : 's that change'} how an operator is notified.` : 'No finding changes how an operator is notified.'],
    ['Reuse blast radius', changedModules.length ? `${changedModules.length} changed module${changedModules.length === 1 ? '' : 's'}, ${s.blastRadius} call sites at most, split by relevance.` : 'No reusable module changed.'],
    ['Undeclared logic', r.undeclared.length ? `${r.undeclared.length} affected routine${r.undeclared.length === 1 ? '' : 's'} without declared safety intent.` : 'No undeclared routine affected.'],
    ['Evidence', `${evidence} evidence items: file, SHA-256, XML location, parser, rule and the logic before and after.`],
    ['Recommended review order', `${s.reviewOrder.length} item${s.reviewOrder.length === 1 ? '' : 's'} to review, most safety-critical first (${review.length} review or undeclared findings).`],
    ['Parser and analysis metadata', `Parser versions, engine ${r.engineVersion}, analysis id ${r.id}, rule catalogue (${r.rules.length} rules).`],
  ]
}

function ReportsView({ result }: { result: AnalysisResult }) {
  const [busy, setBusy] = useState<ReportFormat | null>(null)
  const [last, setLast] = useState<Partial<Record<ReportFormat, { size: number; ms: number }>>>({})
  const base = `interlock-${safeSlug(result.current.metadata.controllerName, 32)}-${safeSlug(result.id, 16)}`

  const generate = async (fmt: (typeof FORMATS)[number]) => {
    setBusy(fmt.id)
    try {
      const { value, elapsedMs } = await engine.report(fmt.id, result)
      const fileName = `${base}.${fmt.ext}`
      downloadBlob(value.data, value.mime, fileName)
      const size = typeof value.data === 'string' ? new TextEncoder().encode(value.data).length : value.data.byteLength
      setLast((l) => ({ ...l, [fmt.id]: { size, ms: elapsedMs } }))
      toast({ title: `${fmt.label} saved`, body: fileName, tone: 'success' })
    } catch (e) {
      toast({ title: 'Report could not be generated', body: e instanceof Error ? e.message : undefined, tone: 'error' })
    } finally {
      setBusy(null)
    }
  }

  const sections = outline(result)

  return (
    <div className="flex flex-col gap-10">
      <PageHeader
        eyebrow="Reports"
        title="Export the review"
        description={`Analysis of ${result.baseline.file.name} → ${result.current.file.name}, ${formatTimestamp(result.analyzedAt)}.`}
      />

      <section aria-labelledby="formats-h" className="flex flex-col gap-4">
        <h2 id="formats-h" className="sr-only">
          Formats
        </h2>
        <div className="grid grid-cols-1 gap-px overflow-hidden rounded-panel bg-line shadow-inset-line md:grid-cols-2">
          {FORMATS.map((f) => {
            const Icon = f.icon
            const info = last[f.id]
            return (
              <div key={f.id} className="flex min-w-0 flex-col gap-4 bg-surface p-5 sm:p-6">
                <div className="flex items-start gap-3">
                  <span className="flex size-10 shrink-0 items-center justify-center rounded-control bg-paper-2 text-ink shadow-inset-line">
                    <Icon aria-hidden="true" className="size-5" />
                  </span>
                  <div className="min-w-0">
                    <h3 className="text-title-3 text-ink">{f.label}</h3>
                    <p className="mt-0.5 text-sm leading-relaxed text-ink-2">{f.body}</p>
                  </div>
                </div>
                <div className="mt-auto flex flex-wrap items-center gap-3">
                  <Button variant={f.id === 'pdf' ? 'primary' : 'secondary'} iconLeft={<FileDown />} loading={busy === f.id} disabled={busy !== null && busy !== f.id} onClick={() => void generate(f)}>
                    Export {f.ext.toUpperCase()}
                  </Button>
                  <span className="il-ident font-mono text-[0.6875rem] text-ink-2">
                    {info ? `${formatBytes(info.size)} · generated in ${formatMs(info.ms)}` : `${base}.${f.ext}`}
                  </span>
                </div>
              </div>
            )
          })}
        </div>
        <div className="flex flex-col gap-3 rounded-card border border-line px-5 py-4 sm:flex-row sm:items-center sm:justify-between">
          <p className="text-sm text-ink">
            Reports are <span className="font-semibold">deterministic</span>: the same analysis always produces the same content. They are generated in this
            browser by the analysis engine and saved directly to your device. Nothing is uploaded.
          </p>
          <LocalModeIndicator variant="compact" className="shrink-0" />
        </div>
      </section>

      <section aria-labelledby="outline-h">
        <div className="mb-4">
          <h2 id="outline-h" className="text-title-2 text-ink">
            What the report contains
          </h2>
          <p className="mt-1 text-sm text-ink-2">Eleven sections, filled from this analysis. PDF and Markdown render the same document.</p>
        </div>
        <ol className="overflow-hidden rounded-panel bg-surface shadow-soft ring-1 ring-line">
          {sections.map(([title, body], i) => (
            <li key={title} className="grid grid-cols-[2.5rem_minmax(0,1fr)] gap-x-3 border-b border-line px-5 py-4 last:border-0 sm:grid-cols-[3rem_16rem_minmax(0,1fr)] sm:px-6">
              <span className="il-num pt-0.5 font-mono text-xs font-semibold text-ink-2">{String(i + 1).padStart(2, '0')}</span>
              <span className="text-[0.9375rem] font-semibold text-ink">{title}</span>
              <span className="il-ident col-start-2 text-sm text-ink-2 sm:col-start-3">{body}</span>
            </li>
          ))}
        </ol>
      </section>
    </div>
  )
}

export function Reports() {
  useDocumentTitle('Reports')
  return (
    <AnalysisGate eyebrow="Reports" title="Reports" description="Deterministic PDF, JSON, CSV and Markdown exports of the analysis, generated in this browser.">
      {(result) => <ReportsView result={result} />}
    </AnalysisGate>
  )
}
